def solve():
    w1, h1, w2, h2 = map(int, input().split())

    total_cells = 0

    # Count cells outside the ship
    for x in range(1, max(w1 + 1, w2 + 1) + 1):
        for y in range(1, h1 + h2 + 2):
            if (x <= w1 and y <= h1) or (w1 < x <= w1 + w2 and h1 < y <= h1 + h2):
                continue
            total_cells += 1

    print(total_cells)
